// Base class (parent)
public class Animal
{
    public string Name { get; set; }

    public Animal(string name)
    {
        Name = name;
    }

    // virtual allows derived classes to override this method
    public virtual void Speak()
    {
        Console.WriteLine($"{Name} makes a sound.");
    }

    // Non-virtual methods cannot be overridden
    public void Sleep()
    {
        Console.WriteLine($"{Name} is sleeping.");
    }
}

// Derived class (child)
public class Dog : Animal
{
    public string Breed { get; set; }

    public Dog(string name, string breed) : base(name)
    {
        Breed = breed;
    }

    // override replaces the base class implementation
    public override void Speak()
    {
        Console.WriteLine($"{Name} (the {Breed}) barks: Woof!");
    }

    // New method specific to Dog
    public void Fetch()
    {
        Console.WriteLine($"{Name} fetches the ball!");
    }
}

public class Cat : Animal
{
    public bool IsIndoor { get; set; }

    public Cat(string name, bool isIndoor) : base(name)
    {
        IsIndoor = isIndoor;
    }

    public override void Speak()
    {
        Console.WriteLine($"{Name} meows: Meow!");
    }
}

// Usage
List<Animal> animals = new()
{
    new Dog("Rex", "Labrador"),
    new Cat("Luna", true)
};

foreach (Animal animal in animals)
{
    animal.Speak(); // Polymorphic: calls correct override per type
}

public abstract class Shape
{
    public string Name { get; set; }

    // Abstract method — no body, must be overridden by derived classes
    public abstract double Area();

    // Virtual method — has a default implementation, CAN be overridden
    public virtual void Display()
    {
        Console.WriteLine($"Shape: {Name}, Area: {Area():F2}");
    }

    // Concrete method — fully implemented, cannot be overridden by default
    public void PrintInfo()
    {
        Console.WriteLine($"[{Name}] Type: {GetType().Name}");
    }
}

public class Circle : Shape
{
    public double Radius { get; set; }

    public Circle(double radius)
    {
        Radius = radius;
        Name = "Circle";
    }

    // Required: must override abstract method
    public override double Area()
    {
        return Math.PI * Radius * Radius;
    }
}

public class Rectangle : Shape
{
    public double Width { get; set; }
    public double Height { get; set; }

    public Rectangle(double width, double height)
    {
        Width = width;
        Height = height;
        Name = "Rectangle";
    }

    public override double Area() => Width * Height;

    public override void Display()
    {
        Console.WriteLine($"Rectangle {Width}x{Height} = Area: {Area():F2}");
    }
}

// Usage
List<Shape> shapes = new()
{
    new Circle(5),
    new Rectangle(4, 6)
};

foreach (Shape shape in shapes)
{
    shape.Display(); // Polymorphism: calls the correct override
}

// Sealed class — cannot be inherited from
public sealed class StringUtils
{
    public static bool IsNullOrEmpty(string? s)
    {
        return string.IsNullOrEmpty(s);
    }
}

// This would cause a compile error:
